const raw = $input.first().json;
const body = raw.body || raw;
const { category, content } = body;

let text = content;
let title = 'Untitled';
let tags = [];

const fmMatch = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
if (fmMatch) {
  const fm = fmMatch[1];
  text = fmMatch[2].trim();
  const titleMatch = fm.match(/^title:\s*(.+)$/m);
  if (titleMatch) title = titleMatch[1].replace(/['"]/g, '').trim();
  const tagsMatch = fm.match(/^tags:\s*\[([^\]]*)\]/m);
  if (tagsMatch) tags = tagsMatch[1].split(',').map(t => t.trim().replace(/['"]/g, ''));
}

const CHUNK_SIZE = 400;
const OVERLAP = 50;
const chunks = [];
let i = 0;
while (i < text.length) {
  chunks.push(text.slice(i, i + CHUNK_SIZE));
  if (i + CHUNK_SIZE >= text.length) break;
  i += CHUNK_SIZE - OVERLAP;
}

return chunks.map((chunk, idx) => ({
  json: {
    text: chunk,
    title,
    category,
    tags,
    chunk_index: idx,
    total_chunks: chunks.length
  }
}));

const embeds = $input.all();
const sources = $('Parse & Chunk').all();

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

const now = new Date().toISOString();
const points = embeds.map((e, i) => {
  const meta = sources[i].json;
  return {
    id: uuid(),
    vector: e.json.embedding,
    payload: {
      text: meta.text,
      title: meta.title,
      category: meta.category,
      tags: meta.tags,
      chunk_index: meta.chunk_index,
      total_chunks: meta.total_chunks,
      ingested_at: now
    }
  };
});

return [{ json: { points, count: points.length, title: sources[0].json.title } }];
